    '서울특별시·경기도 도봉산', 739.50,
    ST_Transform(ST_SetSRID(ST_MakePoint(127.01823397, 37.69354280), 4326), 5179)
);

SELECT set_config('orda.seed.mountain_id', mountain_id::text, true)
FROM public.mountain
WHERE mountain_nm = '도봉산'
  AND use_yn = 'Y';

